const sombra = (x, y, rx, ry = 7) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${S}"/>`;
const svg = (c) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 150" width="240" height="150">${c}</svg>`;

