// Los mismos dibujos en PNG (480×300, fondo #f6f5f2), en base64
const PNG = {
  "portada": "",
  "lateral": "",
  "frontal": "",
  "trasera": "",
  "tres_cuartos_trasera": "",
  "interior": "",
  "motor": "",
  "detalles": ""
  };

/** GET /tienda/guia/<foto>.png */
export function imagenGuia(nombre) {
  const k = String(nombre || '').replace(/\.png$/, '');
  if (!PNG[k]) return { status: 404, headers: { 'Content-Type': 'text/plain' }, body: 'no' };
  return { status: 200, headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800' }, body: Buffer.from(PNG[k], 'base64') };
}
export const urlGuia = (cfg, k = '') => (cfg.servidor ? `${cfg.servidor}/tienda/guia${k ? `/${k}.png` : ''}` : '');

export const CONSEJOS = ['De día, con luz natural (mejor a primera hora o al atardecer). Nada de flash ni contraluz.', 'El coche entero, limpio y centrado, sin cortar el morro ni la trasera.', 'Fondo limpio: sin otros coches, gente ni cubos de basura. Un campo, una calle bonita o una nave vale.', 'Al menos 8 fotos: estas 8 son las que mejor funcionan.'];

/** GET /tienda/guia: la guía entera, para el móvil */
export function paginaGuia() {
  const [p, ...resto] = GUIA;
  const tarjeta = ([k, t, x], grande = false) => `<figure class="${grande ? 'grande' : ''}">${DIBUJOS[k].replace('width="240" height="150"', 'role="img" aria-label="' + esc(t) + '"')}<figcaption><b>${grande ? '1 · ' : ''}${esc(t)}</b><span>${esc(x)}</span></figcaption></figure>`;
  return { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=3600' }, body: `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Cómo hacer las fotos de tu coche · Sidonia</title><meta name="description" content="Las 8 fotos que mejor funcionan en Sidonia, empezando por la portada.">
<style>body{margin:0;background:#f6f5f2;color:#1b1a18;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}
main{max-width:860px;margin:0 auto;padding:32px 16px 48px}.logo{text-align:center;font-weight:700;letter-spacing:.45em;margin:0 0 20px}
h1{margin:0 0 8px;font-size:28px;line-height:1.2;text-align:center}.sub{margin:0 auto 24px;max-width:560px;text-align:center;color:#5c5850;line-height:1.55}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,240px),1fr));gap:14px}
figure{margin:0;padding:14px;border-radius:18px;background:#fff;display:grid;gap:8px;align-content:start}figure svg{width:100%;height:auto;display:block}
figcaption{display:grid;gap:4px}figcaption b{font-size:16px}figcaption span{font-size:14px;line-height:1.5;color:#5c5850}
.grande{grid-column:1/-1;border:2px solid #1b1a18;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);align-items:center;gap:18px;padding:20px}
.grande figcaption b{font-size:20px}.grande figcaption span{font-size:15px}.grande::before{content:'LA MÁS IMPORTANTE';grid-column:1/-1;font-size:12px;font-weight:800;letter-spacing:.14em;color:#8a5a00}
@media(max-width:600px){.grande{grid-template-columns:1fr}}
ul{margin:24px 0 0;padding:18px 18px 18px 36px;border-radius:18px;background:#fff;line-height:1.6;color:#3a3833}li{margin:0 0 6px}</style></head>
<body><main><p class="logo">SIDONIA</p><h1>Cómo hacer las fotos de tu coche</h1>
<p class="sub">Con estas 8 fotos tu anuncio se ve como los de Sidonia y se vende antes. Empieza siempre por la portada: es la que ve todo el mundo.</p>
<div class="grid">${tarjeta(p, true)}${resto.map((x) => tarjeta(x)).join('')}</div>
<ul>${CONSEJOS.map((c) => `<li>${esc(c)}</li>`).join('')}</ul></main></body></html>` };
}

/** Para los emails: la portada en grande y el resto en una rejilla de 2 (tablas: así lo pintan todos los correos) */
export function bloqueGuiaCorreo(cfg) {
  if (!cfg.servidor) return '';
  const [p, ...resto] = GUIA;
  const img = (k, t, w) => `<img src="${esc(urlGuia(cfg, k))}" width="${w}" alt="${esc(t)}" style="display:block;width:100%;max-width:${w}px;height:auto;border:0;border-radius:12px">`;
  const celda = ([k, t, x]) => `<td width="50%" valign="top" style="padding:6px">${img(k, t, 240)}<p style="margin:6px 0 0;font-size:13px;line-height:1.45;color:#3a3833"><b style="color:#1b1a18">${esc(t)}.</b> ${esc(x)}</p></td>`;
  const filas = [];
  for (let i = 0; i < resto.length; i += 2) filas.push(`<tr>${celda(resto[i])}${resto[i + 1] ? celda(resto[i + 1]) : '<td></td>'}</tr>`);
  return `<div style="margin:6px 0 18px">
    <p style="margin:0 0 10px;font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#8a5a00">Así tienen que ser las fotos</p>
    <div style="padding:12px;border:2px solid #1b1a18;border-radius:16px">${img(p[0], p[1], 480)}<p style="margin:10px 0 0;font-size:15px;line-height:1.5;color:#3a3833"><b style="color:#1b1a18">1 · Portada (la más importante).</b> ${esc(p[2])}</p></div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px">${filas.join('')}</table>
    <p style="margin:8px 0 0;font-size:14px"><a href="${esc(urlGuia(cfg))}" style="color:#1b1a18;font-weight:700">Ver la guía de fotos completa ›</a></p>
  </div>`;
}
